//! Federated continual performance/reliability interoperability (`AFA-ids-P21-F24`).
//!
//! The gateway evaluates bounded workload attestations and emits a digest-only reliability
//! result. It never connects to endpoints, retries work, or claims provider completion.

use crate::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID:&str="AFA-ids-P21-F24";
pub const CONTRACT_VERSION:&str="ids-federated-continual-performance-reliability-interoperability-gateway/1.0";
pub const INPUT_SCHEMA:&str="CapabilityWorkload4@1";
pub const OUTPUT_SCHEMA:&str="ReliableCapabilityResult6@1";
pub const CONTENT_TYPE:&str="application/vnd.aurora.reliable-capability-result-6+json";
pub const PRECLINICAL_BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";

#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum WorkloadEvidenceState{Proven,Supported,Unknown,Unmeasured,Contradicted,Negative}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct CapabilityWorkload4{pub workload_id:String,pub capability_id:String,pub endpoint_id:String,pub scope:String,pub expected_tasks:u32,pub completed_tasks:u32,pub retry_count:u32,pub duplicate_events:u32,pub failure_mode:String,pub p95_latency_ms:u64,pub provenance_digest:ContentHash,pub replay_identity:ContentHash,pub evidence_state:WorkloadEvidenceState,pub endpoint_approved:bool,pub local:bool,pub aggregate_only:bool,pub omission_order:Vec<String>,pub negative_result:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct CapabilityWorkloadRequest4{pub schema_version:String,pub request_id:String,pub scope:String,pub latency_slo_ms:u64,pub max_retries:u32,pub workloads:Vec<CapabilityWorkload4>,pub replay_identity:ContentHash,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub network_available:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ReliableCapabilityArtifact6{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub provenance_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ReliableCapabilityResult6{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub scope:String,pub disposition:String,pub workload_order:Vec<String>,pub dependable_order:Vec<String>,pub degraded_order:Vec<String>,pub blocked_order:Vec<String>,pub missing_order:Vec<String>,pub retry_order:Vec<String>,pub timeout_order:Vec<String>,pub duplicate_event_order:Vec<String>,pub omission_order:Vec<String>,pub uncertainty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub replay_identity:ContentHash,pub result_digest:ContentHash,pub artifact:ReliableCapabilityArtifact6,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum PerformanceReliabilityError{#[error("invalid capability workload request: {0}")]Invalid(String),#[error("reliable capability result failed validation: {0}")]Output(String)}
fn nonempty(v:&str)->bool{!v.trim().is_empty()}fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}
pub fn performance_reliability_gateway_manifest()->serde_json::Value{json!({"schema_version":"aurora-research-contract/1.0","capability_id":FEATURE_ID,"version":CONTRACT_VERSION,"owner_crate":"ids","consumers":["reliability engineer","federation operator","research workflow orchestrator"],"behavior":"evaluate bounded capability workload reliability and interoperability attestations","value":"makes retries, latency, duplicates, failures, and missing completion explicit before exchange","input_schema":INPUT_SCHEMA,"output_schema":OUTPUT_SCHEMA,"effects":["exchange:permitted-artifacts","block:unsafe-release"],"permissions":["connect:approved-endpoints"],"autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
impl ReliableCapabilityResult6{pub fn validate(&self)->Result<(),PerformanceReliabilityError>{if self.schema_version!="aurora-research-contract/1.0"||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||self.artifact.content_type!=CONTENT_TYPE||!self.raw_data_local||!self.aggregate_only||!nonempty(&self.request_id)||!nonempty(&self.scope)||self.workload_order.is_empty()||self.effect_receipts.is_empty()||!["qualified","unresolved","blocked"].contains(&self.disposition.as_str()){return Err(PerformanceReliabilityError::Output("reliability identity, locality, workloads, or effects are incomplete".into()));}for v in [&self.workload_order,&self.dependable_order,&self.degraded_order,&self.blocked_order,&self.missing_order,&self.retry_order,&self.timeout_order,&self.duplicate_event_order,&self.omission_order,&self.uncertainty_order,&self.negative_evidence_order,&self.effect_receipts]{if !ordered(v){return Err(PerformanceReliabilityError::Output("reliability ordering is not canonical".into()));}}let all=self.workload_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.dependable_order.iter().chain(&self.degraded_order).chain(&self.blocked_order).cloned().collect::<Vec<_>>();if all.len()!=self.workload_order.len()||parts.len()!=all.len()||BTreeSet::from_iter(parts)!=all{return Err(PerformanceReliabilityError::Output("workload states do not partition".into()));}if !digest(&self.replay_identity)||!digest(&self.result_digest)||self.artifact.content_hash!=self.result_digest||self.artifact.provenance_digests.iter().any(|v|!digest(v)){return Err(PerformanceReliabilityError::Output("reliability digest or artifact metadata is invalid".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("exchange:permitted-artifacts:")){return Err(PerformanceReliabilityError::Output("effect is outside reliability gate".into()));}Ok(())}pub fn digest(&self)->Result<ContentHash,PerformanceReliabilityError>{self.validate()?;ContentHash::of_value(&serde_json::to_value(self).map_err(|e|PerformanceReliabilityError::Output(e.to_string()))?).map_err(|e|PerformanceReliabilityError::Output(e.to_string()))}}
fn validate_request(q:&CapabilityWorkloadRequest4)->Result<(),PerformanceReliabilityError>{if q.schema_version!=INPUT_SCHEMA||!nonempty(&q.request_id)||!nonempty(&q.scope)||q.latency_slo_ms==0||q.workloads.is_empty()||!digest(&q.replay_identity)||!ordered(&q.adversarial_events)||q.boundary!=PRECLINICAL_BOUNDARY||!q.raw_data_local||!q.aggregate_only{return Err(PerformanceReliabilityError::Invalid("request identity, SLO, workloads, digest, locality, or boundary is invalid".into()));}let mut ids=BTreeSet::new();for w in &q.workloads{if !nonempty(&w.workload_id)||!nonempty(&w.capability_id)||!nonempty(&w.endpoint_id)||!nonempty(&w.scope)||!nonempty(&w.failure_mode)||!digest(&w.provenance_digest)||!digest(&w.replay_identity)||!ordered(&w.omission_order)||!ids.insert(w.workload_id.clone()){return Err(PerformanceReliabilityError::Invalid("workload identity, digest, ordering, or uniqueness is invalid".into()));}}Ok(())}
pub fn assess_performance_reliability(q:&CapabilityWorkloadRequest4)->Result<ReliableCapabilityResult6,PerformanceReliabilityError>{validate_request(q)?;let mut rows=q.workloads.clone();rows.sort_by(|a,b|a.workload_id.cmp(&b.workload_id));let ids=rows.iter().map(|w|w.workload_id.clone()).collect::<Vec<_>>();let mut dependable=BTreeSet::new();let mut degraded=BTreeSet::new();let mut blocked=BTreeSet::new();let mut missing=BTreeSet::new();let mut retry=BTreeSet::new();let mut timeout=BTreeSet::new();let mut duplicate=BTreeSet::new();let mut omission=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut provenance=BTreeSet::new();for w in &rows{let id=w.workload_id.clone();provenance.insert(w.provenance_digest.clone());omission.extend(w.omission_order.iter().map(|v|format!("{id}:{v}")));if w.negative_result||w.evidence_state==WorkloadEvidenceState::Negative{negative.insert(format!("{id}:negative-result"));}if !w.endpoint_approved||!w.local||!w.aggregate_only{blocked.insert(id.clone());omission.insert(format!("{id}:endpoint-approval-or-locality"));}else if w.replay_identity!=q.replay_identity{degraded.insert(id.clone());uncertainty.insert(format!("{id}:replay-mismatch"));}else{if w.retry_count>0{retry.insert(id.clone());}if w.duplicate_events>0{duplicate.insert(id.clone());}if w.p95_latency_ms>q.latency_slo_ms{timeout.insert(id.clone());}if w.completed_tasks<w.expected_tasks{missing.insert(id.clone());}if w.retry_count>q.max_retries||w.duplicate_events>0||w.p95_latency_ms>q.latency_slo_ms||w.completed_tasks<w.expected_tasks||!matches!(w.evidence_state,WorkloadEvidenceState::Proven|WorkloadEvidenceState::Supported){degraded.insert(id.clone());uncertainty.insert(format!("{id}:reliability-threshold-or-evidence"));}else{dependable.insert(id);}}}let global=!q.policy_allowed||!q.protected_closure||!q.signed_approval||!q.network_available||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty();if global{blocked.extend(ids.iter().cloned());dependable.clear();degraded.clear();omission.insert("request:security-or-adversarial-gate-blocked".into());}uncertainty.extend(q.adversarial_events.iter().map(|e|format!("adversarial:{e}")));let do_=dependable.iter().cloned().collect::<Vec<_>>();let dgo=degraded.iter().cloned().collect::<Vec<_>>();let bo=blocked.iter().cloned().collect::<Vec<_>>();let disposition=if global||do_.is_empty()&&dgo.is_empty(){"blocked"}else if !dgo.is_empty()||!bo.is_empty(){"unresolved"}else{"qualified"};if disposition!="qualified"{omission.insert("request:reliability-closure-not-ready".into());}let mut payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":q.request_id,"scope":q.scope,"disposition":disposition,"workload_order":ids,"dependable_order":do_,"degraded_order":dgo,"blocked_order":bo,"missing_order":missing.iter().cloned().collect::<Vec<_>>(),"retry_order":retry.iter().cloned().collect::<Vec<_>>(),"timeout_order":timeout.iter().cloned().collect::<Vec<_>>(),"duplicate_event_order":duplicate.iter().cloned().collect::<Vec<_>>(),"omission_order":omission.iter().cloned().collect::<Vec<_>>(),"uncertainty_order":uncertainty.iter().cloned().collect::<Vec<_>>(),"negative_evidence_order":negative.iter().cloned().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let rd=ContentHash::of_value(&payload).map_err(|e|PerformanceReliabilityError::Output(e.to_string()))?;payload["result_digest"]=json!(rd);payload["artifact"]=json!({"artifact_id":format!("reliable-capability-result-6:{}",q.request_id),"content_type":CONTENT_TYPE,"content_hash":rd,"semantic_loss":omission.iter().cloned().collect::<Vec<_>>(),"provenance_digests":provenance.iter().cloned().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("exchange:permitted-artifacts:{}",q.request_id)]}else{vec!["block:unsafe-release".to_string()]});let output:ReliableCapabilityResult6=serde_json::from_value(payload).map_err(|e|PerformanceReliabilityError::Output(e.to_string()))?;output.validate()?;Ok(output)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn w(id:&str)->CapabilityWorkload4{CapabilityWorkload4{workload_id:id.into(),capability_id:"cap:1".into(),endpoint_id:"ep:1".into(),scope:"study:local".into(),expected_tasks:10,completed_tasks:10,retry_count:0,duplicate_events:0,failure_mode:"none".into(),p95_latency_ms:10,provenance_digest:h("p"),replay_identity:h("r"),evidence_state:WorkloadEvidenceState::Proven,endpoint_approved:true,local:true,aggregate_only:true,omission_order:vec![],negative_result:false}}fn q()->CapabilityWorkloadRequest4{CapabilityWorkloadRequest4{schema_version:INPUT_SCHEMA.into(),request_id:"rel:req".into(),scope:"study:local".into(),latency_slo_ms:100,max_retries:2,workloads:vec![w("b"),w("a")],replay_identity:h("r"),policy_allowed:true,protected_closure:true,signed_approval:true,network_available:true,raw_data_local:true,aggregate_only:true,adversarial_events:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified(){assert_eq!(assess_performance_reliability(&q()).unwrap().disposition,"qualified")}#[test]fn retry_is_visible(){let mut x=q();x.workloads[0].retry_count=1;assert!(!assess_performance_reliability(&x).unwrap().retry_order.is_empty())}#[test]fn network_blocks(){let mut x=q();x.network_available=false;assert_eq!(assess_performance_reliability(&x).unwrap().disposition,"blocked")} }
